fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // If maxsplit is zero, no splitting should be performed.
    // So each inner Vec contains exactly the original string.
    if maxsplit == 0 {
        return a.into_iter().map(|s| vec![s]).collect();
    }

    let sep = &sep; // Use a string slice for splitting.

    a.into_iter()
        .map(|s| {
            // If the string is empty, return a single empty string.
            if s.is_empty() {
                return vec![String::new()];
            }

            // Use rsplitn to split from the right with maxsplit + 1 parts.
            // rsplitn produces at most n parts from the right side.
            let parts: Vec<String> = s.rsplitn((maxsplit as usize) + 1, sep)
                .map(|part| part.to_string())
                .collect();
            
            // rsplitn returns parts in reverse order from right to left,
            // but the problem wants the split parts in order from left to right
            // (normal substring order), so we must reverse the vector.
            let mut parts = parts;
            parts.reverse();
            parts
        })
        .collect()
}